head.script:
scwin.confirmMsg = function() {
    return confirm("닫아도 됩니까?");
}
scwin.confirmMsg1 = function() {
    return confirm("close?");
}
scwin.neverClose = function() {
    alert("난 절대 안닫히는 창입니다.");
    return false;
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getDomById('windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow0') == null;
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getDomById('windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow1') == null;
}
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getDomById('windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow2') == null;
}
scwin.checkVal4 = function() {
    return WebSquare.wUnit.getDomById('windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow3') == null;
}
scwin.checkVal5 = function() {
    return WebSquare.wUnit.getDomById('windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow0') == null;
}
scwin.checkVal6 = function() {
    return WebSquare.wUnit.getDomById('windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow0') == null;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 windowContainer1 의 closeType 을 확인한다. 
    //1. In the Source tab, check the closeType of windowContainer1.
    //Verify step 1. closeType = 'all'
    //1. closeType = 'all'
    //Test step 2. useFixButton 를 확인한다.
    //2. Check useFixButton.
    //Verify step 2. useFixButton = 'true'
    //2. useFixButton = 'true'
    //Test step 3. 1번 샘플 실행 후 브라우저에서 우측에 Eclipse / Danawa / Google / 버튼을 클릭한다.
    //3. After running sample 1, click the Eclipse / Danawa / Google / button on the right side of your browser.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 3. 창이 생성된다.
    //3. A window is created.
    //WebSquare.wUnit.addCommand("assert", "typeof windowContainer1_nameLayer_windowContainer1_subWindow3 == 'object'", "true");
    //WebSquare.wUnit.addCommand("assert", "typeof windowContainer1_nameLayer_windowContainer1_subWindow4 == 'object'", "true");
    //WebSquare.wUnit.addCommand("assert", "typeof windowContainer1_nameLayer_windowContainer1_subWindow5 == 'object'", "true");
    //Test step 4. 생성된 windowContainer 하단에 고정 핀을 클릭한다. (그림에 초록테두리 참고)
    //4. Click the pin at the bottom of the generated windowContainer. (Note the green border on the picture)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2windowContainer_nameLayer_fixOff')[3].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 4. 고정핀이 활성화된다.
    //4. The pin is activated.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2windowContainer_nameLayer_fixOff.w2windowContainer_nameLayer_fixOn').length > 0", "true");
    //Test step 5. 모두 닫기버튼을 클릭한다. (그림에 빨간테두리 참고)
    //5. Click the Close All button. (Note the red border on the picture)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('windowContainer1_closeAll').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 5. 생성된 창들이 모두 닫힌다.
    //5. All created windows are closed.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal5()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal6()", "true");
    //Test step 9. 3번 샘플 실행 후 Source 탭에서 windowContainer1 의 closeType 을 noneFixedWindow 로 변경한다. (all -> FixedWindow)
    //9. After running sample 3, in the Source tab, change the closeType of windowContainer1 to noneFixedWindow. (all -> FixedWindow)
    //Verify step 9. closeType = 'fixedWindow'
    //9. closeType = 'fixedWindow'
    //Test step 10. 생성된 windowContainer 하단에 고정 핀을 클릭한다. (그림에 초록테두리 참고)
    //10. Click the pin at the bottom of the generated windowContainer. (Note the green border on the picture)
    //Verify step 10. 고정핀이 활성화된다.
    //10. The pin is activated.
    //Test step 11. 모두 닫기버튼을 클릭한다. (그림에 빨간테두리 참고)
    //11. Click the Close All button. (Note the red border on the picture)
    //Verify step 11. 고정핀 설정을 한 창들이 모두 닫힌다.
    //11. All the windows that are set with the fixed pin are closed.
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    WebSquare.wUnit.getObjById('windowContainer1').createWindow("naver", "", "http://www.naver.com", "네이버", "1", "", "");
    WebSquare.wUnit.getObjById('windowContainer1').createWindow("daum", "", "http://www.daum.net", "다음", "2", "", "");
    //windowContainer1.createWindow( "ppomppu" , "" , "http://www.ppomppu.co.kr/index.php", "뽐뿌", "3", "", "neverClose");
    WebSquare.wUnit.getObjById('windowContainer1').createWindow("ppomppu", "", "http://www.ppomppu.co.kr/index.php", "뽐뿌", "3", "", "");
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 02-Apr-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
